<script setup lang="ts">
import {computed,ref} from 'vue';import {useRoute,useRouter} from 'vue-router';import {useAuthStore} from '@/stores/auth';
const a=useAuthStore(),r=useRouter(),route=useRoute(),open=ref(false);
const initials=computed(()=>{const parts=(a.displayName||a.username).trim().split(/\s+/).filter(Boolean);return parts.length>=2?(parts[0][0]+parts[1][0]).toUpperCase():(a.displayName||a.username).slice(0,2).toUpperCase()});
const items=computed(()=>[{to:'/mi-cuenta',label:'Mi cuenta',icon:'◈',roles:['CLIENTE']},{to:'/dashboard',label:'Resumen',icon:'▦',roles:['ADMIN','ACTUARIO','AGENTE']},{to:'/clientes',label:'Clientes y vehículos',icon:'◉',roles:['ADMIN','AGENTE']},{to:'/tarifas',label:'Tablas tarifarias',icon:'%',roles:['ADMIN','ACTUARIO']},{to:'/cotizaciones',label:'Cotizaciones',icon:'◎',roles:['ADMIN','AGENTE']},{to:'/polizas',label:'Pólizas y siniestros',icon:'▤',roles:['ADMIN','AGENTE']},{to:'/renovaciones',label:'Renovaciones',icon:'↻',roles:['ADMIN','AGENTE']},{to:'/seguridad',label:'Seguridad MFA',icon:'*'}].filter(i=>!i.roles||i.roles.includes(a.role)));
function out(){a.logout();r.push('/login')}
</script>
<template><div class="shell"><aside :class="['sidebar',{open}]"><div class="brand"><div class="brand-mark">A</div><div><strong>Andina</strong><span>Seguros</span></div></div><nav><RouterLink v-for="i in items" :key="i.to" :to="i.to" @click="open=false"><b>{{i.icon}}</b>{{i.label}}</RouterLink></nav><div class="side-footer"><small>Sesión activa</small><strong>{{a.displayName}}</strong><span>{{a.role}}</span><button class="link-btn" @click="out">Cerrar sesión</button></div></aside><main><header class="topbar"><button class="menu" @click="open=!open">☰</button><div><h1>{{String(route.meta.title||'Gestión de seguros')}}</h1><p>Motor de tarificación y ciclo de pólizas</p></div><div class="avatar">{{initials}}</div></header><section class="content"><RouterView/></section></main></div></template>
